# PlatformIO pre-build script: gzips web/index.html into src/generated/web_index_html.h,
# so the web UI is part of the firmware image (one OTA update = firmware + UI).
import gzip
import hashlib
import os

Import("env")  # noqa: F821  (provided by PlatformIO/SCons)

root = env.subst("$PROJECT_DIR")  # noqa: F821
src = os.path.join(root, "web", "index.html")
out_dir = os.path.join(root, "src", "generated")
out = os.path.join(out_dir, "web_index_html.h")

with open(src, "rb") as f:
    raw = f.read()
data = gzip.compress(raw, compresslevel=9, mtime=0)

lines = [
    "// GENERATED by tools/embed_web.py from web/index.html - do not edit",
    "#pragma once",
    "#include <stddef.h>",
    "#include <stdint.h>",
    # fingerprint of the UI: an open page reloads itself when it changes (e.g. after an OTA update)
    f'#define WEB_UI_HASH "{hashlib.sha1(raw).hexdigest()[:12]}"',
    f"static const size_t WEB_INDEX_HTML_GZ_LEN = {len(data)};",
    "static const uint8_t WEB_INDEX_HTML_GZ[] = {",
]
for i in range(0, len(data), 20):
    lines.append("  " + ",".join(f"0x{b:02x}" for b in data[i : i + 20]) + ",")
lines.append("};")
content = "\n".join(lines) + "\n"

os.makedirs(out_dir, exist_ok=True)
old = None
if os.path.exists(out):
    with open(out, "r", encoding="ascii") as f:
        old = f.read()
if old != content:
    with open(out, "w", encoding="ascii", newline="\n") as f:
        f.write(content)
    print(f"embed_web: web/index.html {len(raw)} B -> {len(data)} B gzip")
